  `last_update` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`product_ID`,`category_ID`),
  KEY `fk_tbd_prod_cat_category` (`category_ID`),
  CONSTRAINT `fk_tbd_prod_cat_category` FOREIGN KEY (`category_ID`) REFERENCES `tbc_categories` (`ID`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_tbd_prod_cat_product` FOREIGN KEY (`product_ID`) REFERENCES `tb_products` (`ID`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
